//! The glue of the `nan` component (46) for the module that hosts it, generated by `tools/gen_vtables.py` from `modules/mod_nan/API.md`; do not edit.
//!
//! [`Api`] is what the module implements. [`dispatch`] serves a request (a method number and the fields map: the runtime has parsed the
//! envelope). The existing native table remains runtime-owned.
#![allow(clippy::all, dead_code)]
use xip_abi::cbor::Writer;
use xip_abi::fields as f;
use xip_abi::{Hw, ERR_ARG, ERR_SIZE, ERR_UNSUPPORTED, PowerInfo, PowerSleep};

pub const COMPONENT: i32 = 46;
pub const M_POWERINFO: i32 = 13;
pub const M_POWERSLEEP: i32 = 14;
pub const M_DUMP_LOCKS: i32 = 15;

/// What the module implements. Every method returns `Err(code)` with a negative `ERR_*`.
pub trait Api {
    /// 13. The power state and the FreeRTOS numbers
    fn powerinfo(&mut self, hw: &Hw, response: &mut PowerInfo) -> Result<(), i32>;
    /// 14. Returns at once; the sleeps run on the host worker with `awake_ms` awake between them so modules run.
    fn powersleep(&mut self, hw: &Hw, request: &PowerSleep) -> Result<(), i32>;
    /// 15. Who keeps the CPU frequency up or light sleep out (`esp_pm_dump_locks`).
    fn dump_locks(&mut self, hw: &Hw) -> Result<(), i32>;
}

fn decode_powersleep(fields: &[u8], r: &mut PowerSleep) -> Result<(), i32> {
    if let Some(v) = f::get_uint(fields, 1)? { r.duration_ms = u32::try_from(v).map_err(|_| ERR_ARG)?; }
    if let Some(v) = f::get_uint(fields, 2)? { r.cycles = u16::try_from(v).map_err(|_| ERR_ARG)?; }
    if let Some(v) = f::get_uint(fields, 3)? { r.awake_ms = u16::try_from(v).map_err(|_| ERR_ARG)?; }
    Ok(())
}

fn encode_powerinfo(r: &PowerInfo, out: &mut [u8]) -> Result<usize, i32> {
    let mut w = Writer::new(out);
    w.map(27);
    w.uint(1).uint(r.state as u64);
    w.uint(2).uint(r.pm_configured as u64);
    w.uint(3).uint(r.auto_light_sleep as u64);
    w.uint(4).uint(r.tickless_idle as u64);
    w.uint(5).uint(r.cpu_mhz as u64);
    w.uint(6).uint(r.min_mhz as u64);
    w.uint(7).uint(r.max_mhz as u64);
    w.uint(8).uint(r.tick_hz as u64);
    w.uint(9).uint(r.cycles_left as u64);
    w.uint(10).uint(r.wake_cause as u64);
    w.uint(11).uint(r.promiscuous as u64);
    w.uint(12).uint(r.sleep_attempts as u64);
    w.uint(13).uint(r.sleep_entries as u64);
    w.uint(14).uint(r.sleep_skipped as u64);
    w.uint(15).uint(r.last_requested_us as u64);
    w.uint(16).uint(r.last_duration_us as u64);
    w.uint(17).uint(r.last_resume_us as u64);
    w.uint(18).uint(r.tasks as u64);
    w.uint(19).uint(r.ticks as u64);
    w.uint(20).uint(r.heap_free as u64);
    w.uint(21).uint(r.heap_min as u64);
    w.uint(22).uint(r.heap_largest as u64);
    w.uint(23).uint(r.filter_dropped as u64);
    w.uint(24).uint(r.promisc_frames as u64);
    w.uint(25).uint(r.soft_sleep as u64);
    w.uint(26).uint(r.active_window as u64);
    w.uint(27).uint(r.ip_sockets as u64);
    w.finish().map(|b| b.len()).ok_or(ERR_SIZE)
}

/// Serve method `method` with the request `fields`; the response map goes to `out`. Returns its length. An unknown method is `ERR_UNSUPPORTED`.
pub fn dispatch<T: Api>(t: &mut T, hw: &Hw, method: i32, fields: &[u8], out: &mut [u8]) -> Result<usize, i32> {
    match method {
        M_POWERINFO => {
            let mut response = PowerInfo::default();
            t.powerinfo(hw, &mut response)?;
            encode_powerinfo(&response, out)
        }
        M_POWERSLEEP => {
            let mut request = PowerSleep::default();
            decode_powersleep(fields, &mut request)?;
            t.powersleep(hw, &request)?;
            let mut w = Writer::new(out);
            w.map(0);
            w.finish().map(|b| b.len()).ok_or(ERR_SIZE)
        }
        M_DUMP_LOCKS => {
            t.dump_locks(hw)?;
            let mut w = Writer::new(out);
            w.map(0);
            w.finish().map(|b| b.len()).ok_or(ERR_SIZE)
        }
        _ => Err(ERR_UNSUPPORTED),
    }
}

